def get_number():
    """Get a valid number from user input."""
    while True:
        try:
            num = float(input("Enter a number: "))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Get a valid arithmetic operation from user input."""
    while True:
        operation = input("Enter an operation (+, -, *, /): ").upper()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the given arithmetic operation on two numbers."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError(f"Invalid operation '{operation}'.")

